});

test('approvalText', () => {
  assert.equal(approvalText({ approvedAt: '2026-10-07', approvedBy: 'Tom' }), '2026-10-07 by Tom');
  assert.equal(approvalText({ approvedAt: '2026-10-07', approvedBy: null }), '2026-10-07');
