  r.commit(regText('a.org', 'b.org', 'c.org'), '2026-10-07T10:00:00-05:00');
  writeFileSync(join(r.dir, 'SOURCE-ALLOWLIST.md'), DOC);
  const before = readFileSync(join(r.dir, REGFILE), 'utf8');
